<?php
$id = req_int('id'); $c = $id ? customer_get($id) : null; if ($id && !$c) throw new UserError('مشتری یافت نشد');
$f = ['kind' => ['نوع', 'select', 1, ['person' => 'شخصِ حقیقی', 'org' => 'سازمان/حقوقی']], 'name' => ['نام', 'text', 1], 'mobile' => ['موبایل (یکتا)', 'text'], 'national_id' => ['کد/شناسهٔ ملی', 'text'], 'economic_code' => ['کدِ اقتصادی', 'text'], 'postal_code' => ['کدِ پستی', 'text'], 'phone' => ['تلفن', 'text'],
    'address' => ['نشانی', 'text'], 'grade_id' => ['گریدِ قیمت', 'select', 0, ui_opts("SELECT id, name FROM grades WHERE kind='customer'")], 'notes' => ['یادداشت', 'textarea']];
if (can('customers.credit')) $f += ['credit_limit' => ['سقفِ نسیه', 'money'], 'is_partner' => ['همکارِ فروش', 'check'], 'partner_grade_id' => ['گریدِ همکار', 'select', 0, ui_opts("SELECT id, name FROM grades WHERE kind='partner'")]];
echo ui_card($c ? $c['name'] . ($c['merged_into'] ? ' (ادغام‌شده)' : '') : 'مشتریِ تازه', can('customers.edit') ? ui_form('customer_save', $f, $c ?? ['kind' => 'person'], ['hidden' => $c ? ['id' => $c['id']] : [], 'then' => 'go:index.php?p=customer&id={id}']) : '<p>' . h($c['mobile'] ?? '') . '</p>');
if (!$c) return;
if ($c['is_partner'] && can('partner.manage')) echo ui_card('واریز به حساب (همکار)', '<p class="muted">اگر روشن باشد، در صندوق برای این همکار «واریز به حساب» می‌آید: سفارش ثبت و رزرو می‌شود، همکار فیش می‌دهد و پس از تأییدِ حسابداری کالا خارج می‌شود. شمارهٔ حساب فقط از حساب‌های بانکیِ تعریف‌شده می‌آید.</p>'
    . ui_form('ptr_save', ['on' => ['«واریز به حساب» برای این همکار', 'check'], 'acc' => ['حسابِ واریز', 'select', 0, ui_opts("SELECT id, title name FROM bank_accounts WHERE active=1")]], ['on' => $c['partner_xfer'] ?? 0, 'acc' => $c['partner_xfer_acc'] ?? ''], ['hidden' => ['customer_id' => $id]]));
$bal = customer_balance($id); $wal = wallet_balance($id);
echo '<div class="stats">' . ui_stat('بدهیِ نسیه', $bal) . ui_stat('سقفِ نسیه', $c['credit_limit']) . ui_stat('کیف پول', $wal) . ui_stat('تعدادِ خرید', (int)val("SELECT COUNT(*) FROM sales WHERE customer_id=?", [$id]), false) . ui_stat('جمعِ خرید', (int)val("SELECT COALESCE(SUM(total),0) FROM sales WHERE customer_id=?", [$id])) . '</div><div class="cols">';
echo ui_card('سابقهٔ خرید', ui_table(['number' => 'شماره', 'd' => ['تاریخ', 'date'], 'seller' => 'فروشنده', 'total' => ['مبلغ', 'money']], customer_history($id), ['href' => fn($r) => page_url('sale', ['id' => $r['id']])]));
if (can('customers.credit')) echo ui_card('دریافت از مشتری / شارژِ کیف پول', ui_form('customer_pay', ['amount' => ['مبلغ', 'money', 1], 'target' => ['بابت', 'select', 1, ['credit' => 'تسویهٔ نسیه', 'wallet' => 'شارژِ کیف پول']], 'method' => ['روش', 'select', 1, ['cash' => 'نقد (شیفتِ باز)', 'card' => 'کارت‌خوان', 'transfer' => 'کارت‌به‌کارت']],
    'bank_account_id' => ['حسابِ بانکی', 'select', 0, ui_opts("SELECT id, title name FROM bank_accounts WHERE active=1")], 'note' => ['یادداشت', 'text']], [], ['hidden' => ['customer_id' => $id]])
    . ui_table(['at' => ['زمان', 'datetime'], 'kind' => 'نوع', 'amount' => ['مبلغ', 'money'], 'note' => 'شرح', 'due_date' => ['سررسید', 'date']], rows("SELECT * FROM customer_ledger WHERE customer_id=? ORDER BY id DESC LIMIT 50", [$id])));
// ── نسیه: قولِ پرداخت، چک‌ها
if (can('customers.credit') || can('customers.view')) {
    $ps = rows("SELECT * FROM credit_promises WHERE customer_id=? ORDER BY status='open' DESC, due_date DESC LIMIT 30", [$id]);
    echo ui_card('قولِ پرداخت', '<p class="muted">اگر جنسی برده و پولش مانده، تاریخی را که قول داده ثبت کنید. یک روز پیش و سرِ موعد به مدیران (داشبورد، بله، پیامک) هشدار می‌رود و اگر بخواهید به خودش هم پیامک/بله.</p>'
        . (can('customers.credit') ? ui_form('promise_save', ['amount' => ['مبلغ (خالی = کلِ بدهی)', 'money'], 'due' => ['تاریخِ قول', 'date', 1], 'note' => ['یادداشت', 'text'], 'sms_customer' => ['یادآوریِ پیامکی به خودش', 'check'], 'bale_customer' => ['یادآوری در بله به خودش', 'check']], [], ['hidden' => ['customer_id' => $id], 'submit' => 'ثبتِ قول']) : '')
        . ui_table(['amount' => ['مبلغ', 'money'], 'due_date' => ['موعد', 'date'], 'status' => ['وضعیت', fn($r) => ui_badge(promise_statuses()[$r['status']] ?? $r['status'], $r['status'] === 'kept' ? 'ok' : ($r['status'] === 'open' ? ($r['due_date'] < today() ? 'err' : 'warn') : ''))], 'note' => 'یادداشت',
            'a' => ['', fn($r) => $r['status'] === 'open' && can('customers.credit') ? ui_btn_api('عمل شد', 'promise_set', ['id' => $r['id'], 'status' => 'kept'], ['class' => 'sm']) . ' ' . ui_btn_api('عمل نشد', 'promise_set', ['id' => $r['id'], 'status' => 'broken'], ['class' => 'sm']) : '']], $ps, ['empty' => '—']));
    $chs = rows("SELECT * FROM cheques WHERE party_type='customer' AND party_id=? ORDER BY due_date DESC LIMIT 30", [$id]);
    echo ui_card('چک‌ها', (can('cheques.manage') || can('customers.credit') ? ui_form('cheque_receive', ['number' => ['شمارهٔ چک', 'text', 1], 'sayad' => ['صیادی (۱۶ رقم)', 'ltr'], 'amount' => ['مبلغ', 'money', 1], 'due' => ['سررسید', 'date', 1], 'bank' => ['بانک', 'text'], 'drawer' => ['صاحبِ حساب', 'text']], [], ['hidden' => ['customer_id' => $id], 'submit' => 'دریافتِ چک (از بدهی کم می‌شود)']) : '')
        . ui_table(['number' => ['شماره', 'num'], 'amount' => ['مبلغ', 'money'], 'due_date' => ['سررسید', 'date'], 'status' => ['وضعیت', fn($r) => ui_badge(cheque_statuses()[$r['status']] ?? $r['status'])]], $chs, ['empty' => '—']) . '<p><a href="' . h(page_url('cheques')) . '">مدیریتِ چک‌ها ←</a></p>');
}
// ── نشانی‌ها و لینکِ ثبتِ نشانی
$ads = addresses_of($id);
echo ui_card('نشانی‌ها', ui_table(['t' => ['نشانی', fn($r) => h(address_text($r)) . ($r['is_default'] ? ' ' . ui_badge('پیش‌فرض', 'ok') : '') . ($r['source'] === 'link' ? ' ' . ui_badge('از لینک') : '') . ($r['lat'] ? ' <a target="_blank" href="https://www.openstreetmap.org/?mlat=' . $r['lat'] . '&mlon=' . $r['lng'] . '#map=17/' . $r['lat'] . '/' . $r['lng'] . '">📍</a>' : '')],
    'postal_code' => ['کدِ پستی', 'code'], 'receiver_name' => ['گیرنده', fn($r) => h(trim($r['receiver_name'] . ' ' . fa_num((string)$r['receiver_mobile'])))], 'a' => ['', fn($r) => can('customers.edit') ? ui_btn_api('حذف', 'address_delete', ['id' => $r['id'], 'customer_id' => $r['customer_id']], ['class' => 'sm', 'confirm' => 'حذف شود؟']) : '']], $ads, ['empty' => 'نشانی‌ای ثبت نشده.'])
    . (can('ship.manage') || can('customers.edit') || can('pos.use') ? '<div class="actions">' . ui_btn_api('لینکِ ثبتِ نشانی (پیامک)', 'addr_link', ['customer_id' => $id, 'sms' => 1], ['class' => 'sm', 'then' => 'none']) . ' ' . ui_btn_api('لینکِ نشانیِ پستیِ کامل (پیامک)', 'addr_link', ['customer_id' => $id, 'sms' => 1, 'postal' => 1], ['class' => 'sm', 'then' => 'none']) . ' ' . ui_btn_api('فقط لینک (کپی)', 'addr_link', ['customer_id' => $id], ['class' => 'sm', 'then' => 'none']) . '</div>' : '')
    . (can('customers.edit') ? '<details><summary>افزودنِ نشانی</summary>' . ui_form('address_save', ['title' => ['عنوان (خانه، مغازه…)', 'text'], 'province' => ['استان', 'text'], 'city' => ['شهر', 'text', 1], 'address' => ['نشانی', 'textarea', 1], 'plaque' => ['پلاک', 'text'], 'unit' => ['واحد', 'text'], 'postal_code' => ['کدِ پستی', 'ltr'], 'receiver_name' => ['گیرنده', 'text'], 'receiver_mobile' => ['موبایلِ گیرنده', 'ltr']], [], ['hidden' => ['customer_id' => $id]]) . '</details>' : ''));
// ── بله و فهرستِ قیمتِ همکار
if (can('customers.edit')) echo ui_card('بله', bale_on() ? (!empty($c['bale_chat_id']) ? '<p class="ok">به بله وصل است؛ یادآوری‌ها (اگر خواسته شود) آنجا هم می‌رود.</p>' . ui_btn_api('قطعِ اتصال', 'bale_unlink', ['kind' => 'customer', 'id' => $id], ['class' => 'sm']) : '<p class="muted">کدِ اتصال را به مشتری بدهید تا برای بات بفرستد.</p>' . (!empty($c['bale_code']) ? '<p>کد: <b dir="ltr">' . h($c['bale_code']) . '</b>' . (bale_link_url($c['bale_code']) ? ' — <span dir="ltr">' . h(bale_link_url($c['bale_code'])) . '</span>' : '') . '</p>' : '') . ui_btn_api('گرفتنِ کدِ اتصال', 'bale_link', ['kind' => 'customer', 'id' => $id], ['class' => 'sm', 'then' => 'reload'])) : '<p class="muted">باتِ بله تنظیم نشده است («هشدارها و بله»).</p>');
if ($c['is_partner'] && can('partner.manage')) { $pl = partner_price_list($id);
    echo ui_card('فهرستِ قیمتِ همکاری (' . fa_num(count($pl)) . ' کالا)', ui_table(['name' => 'کالا', 'retail' => ['قیمتِ مصرف‌کننده', 'money'], 'price_one' => ['همکار (۱ عدد)', 'money'], 'price_max' => ['همکار (بیشینه)', 'money'], 'qty_max' => ['از تعداد', 'num']], array_slice($pl, 0, 50), ['empty' => 'برای گریدِ این همکار قیمتی تعریف نشده است.'])
        . '<div class="actions">' . ui_btn_api('لینکِ فهرست (۳۰ روز)', 'partner_list_link', ['customer_id' => $id], ['class' => 'sm', 'then' => 'none']) . ' ' . ui_btn_api('فرستادنِ لینک با پیامک/بله', 'partner_list_send', ['customer_id' => $id], ['class' => 'sm']) . ' <a class="btn sm" href="' . h(page_url('partner_prices')) . '">ویرایشِ قیمت‌ها</a></div>'); }
echo ui_card('تماس و پیگیری', ui_form('call_add', ['result' => ['نتیجه', 'select', 1, call_results()], 'direction' => ['جهت', 'select', 0, ['out' => 'خروجی', 'in' => 'ورودی']], 'note' => ['یادداشت', 'textarea'], 'internal' => ['یادداشتِ داخلی (مشتری نمی‌بیند)', 'check'], 'next_at' => ['یادآوری در تاریخ', 'date']], [], ['hidden' => ['customer_id' => $id]])
    . ui_table(['at' => ['زمان', 'datetime'], 'un' => 'کارمند', 'result' => ['نتیجه', fn($r) => h(call_results()[$r['result']] ?? '')], 'note' => 'یادداشت', 'next_at' => ['یادآوری', 'date']], rows("SELECT k.*, u.name un FROM calls k LEFT JOIN users u ON u.id=k.user_id WHERE customer_id=? ORDER BY k.id DESC LIMIT 50", [$id])));
echo ui_card('افرادِ سازمان', ui_table(['name' => 'نام', 'role' => 'سمت', 'mobile' => ['موبایل', 'num']], rows("SELECT * FROM customer_people WHERE customer_id=?", [$id]), ['empty' => '—']) . (can('customers.edit') ? ui_form('customer_person', ['name' => ['نام', 'text', 1], 'role' => ['سمت', 'text'], 'mobile' => ['موبایل', 'text']], [], ['hidden' => ['customer_id' => $id], 'submit' => 'افزودن']) : ''));
if (can('customers.edit')) echo ui_card('ادغام (یک آدم، یک پرونده)', ui_form('customer_merge', ['drop' => ['شمارهٔ پروندهٔ تکراری که در این پرونده ادغام شود', 'int', 1]], [], ['hidden' => ['keep' => $id], 'confirm' => 'همهٔ سوابقِ پروندهٔ دوم به این پرونده منتقل می‌شود. ادامه؟', 'submit' => 'ادغام']));
echo '</div>';
